"""Prepare source-grounded decisions; this script does not change live inputs."""
import json, csv
from pathlib import Path
from datetime import datetime, timezone
p=Path(__file__).parent
spec={'evidence':{},'identities':[],'decisions':[],'names':[],'human_review':[]}
def case(code,url,note,keys=None,roles=None,groups=None,key=None,name=None,aff='independent',status='verified',chain=None,category='not_flagged',action=None):
    spec['evidence'][code]={'url':url,'note':note+' Evidence packet: data/validation/'+p.name+'; source fields and coordinates retained.'}
    if keys:
        spec['identities'].append({'case':code,'keys':keys,'roles':roles,'groups':groups or [code.lower()]*len(keys)})
        key=key or keys[0]
    spec['decisions'].append({'case':code,'key':key,'aff':aff,'status':status,'chain':chain,'category':category})
    if name: spec['names'].append({'case':code,'key':key,'name':name})
    if action: spec['human_review'].append({'case':code,'source_id':key,'status':'pending','action':action,'evidence_url':url})

